import { forwardRef } from "react";
import { clsx } from "clsx";

import { RichTextClasses } from "../rich-text.styles";

export type RichTextToolbarProps = React.ComponentPropsWithoutRef<"div">;

export const RichTextToolbar = forwardRef<HTMLDivElement, RichTextToolbarProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(RichTextClasses.toolbar, className)} {...props}>
        {children}
      </div>
    );
  },
);

RichTextToolbar.displayName = "RichText.Toolbar";
